import logging
import ssl
import typing

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.aio.interface import IReactor
from jsilib.base import IClosable

from . import _globals, exc
from ._endpoint import Endpoint, dump_to_url
from .acceptor import ForwardingAcceptor
from .interface import IStream, ITask
from .streams import QueueReadOnlyStream

logger = logging.getLogger(_globals.LOGGER_NAME)


class TCPServer(IClosable):

    def __init__(self, reactor: IReactor, forwarder: ForwardingAcceptor):
        self._reactor = reactor
        self._forwarder = forwarder
        self._active_connections: typing.Dict[int, IClosable] = {}
        self._server_task: ITask = None
        self._closed = False

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.info('TCP server closing started...')
            if self._server_task is not None:
                await self._server_task.cancel()
            for connection in dict(self._active_connections).values():
                await connection.close()
            logger.info('TCP server closed.')

    async def bind(self, endpoint: Endpoint):

        async def do_bind():

            @_utils.log_exceptions(logger)
            async def serve_forever():

                async def run():
                    async with server:
                        await server.serve_forever()

                async def run_py36():
                    try:
                        await server.serve_forever()
                    finally:
                        await server.wait_closed()

                logger.info('TCP server is running at %s', dump_to_url(endpoint))
                if _utils.python_version_gt(3, 6):
                    await run()
                else:
                    await run_py36()

            @_utils.log_exceptions(logger)
            async def serve_forever_py36():
                logger.info('TCP server is running at %s', dump_to_url(endpoint))
                try:
                    await server.serve_forever()
                finally:
                    await server.wait_closed()

            ssl_context = None
            host, port = endpoint.netloc.require_host_port()
            if endpoint.scheme == 'tcp+ssl':
                ssl_context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
                ssl_context.load_cert_chain(endpoint.query['certfile'][0], keyfile=endpoint.query['keyfile'][0])
            server = await self._reactor.event_loop.create_server(
                lambda: self._ServerConnection(self), host, port, ssl=ssl_context
            )
            self._server_task = self._reactor.run(serve_forever())

        try:
            await do_bind()
        except Exception as e:
            raise exc.BindFailedError(f"Couldn't bind a TCP server to {dump_to_url(endpoint)}", original_exc=e)

    class _ServerConnection(asyncio.Protocol, IStream):

        def __init__(self, acceptor: 'TCPServer'):
            self._id = _utils.next_unique_id(self.__class__)
            self._acceptor = acceptor

        def connection_made(self, transport: asyncio.transports.BaseTransport):
            logger.info(
                'TCP server accepted connection from %r (id: %d)', transport.get_extra_info('peername'), self._id
            )
            acceptor = self._acceptor
            self._transport = transport
            self._target = _TCPStream(acceptor._reactor, transport)
            acceptor._active_connections[self._id] = self
            acceptor._forwarder.dispatch(self)

        def connection_lost(self, exc: typing.Optional[Exception]):
            logger.info('TCP server connection lost (id: %d)', self._id)
            acceptor = self._acceptor
            del acceptor._active_connections[self._id]
            acceptor._reactor.run(self.close())

        def data_received(self, data: bytes):
            self._target.data_received(data)

        def is_closed(self) -> bool:
            return self._target.is_closed()

        async def close(self):
            return await self._target.close()

        async def read(self, count: int) -> bytes:
            return await self._target.read(count)

        async def write(self, data: bytes) -> int:
            return await self._target.write(data)

        def get_write_buffer_size(self) -> int:
            return self._target.get_write_buffer_size()


class TCPClient(IClosable):

    def __init__(self, reactor: IReactor):
        self._reactor = reactor
        self._closed = False
        self._active_connections: typing.Dict[int, IClosable] = {}

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.info('TCP client closing started...')
            for closable in self._active_connections.values():
                await closable.close()
            logger.info('TCP client closed.')

    async def connect(self, endpoint: Endpoint) -> IStream:

        async def do_connect():
            ssl_context = None
            host, port = endpoint.netloc.require_host_port()
            if endpoint.scheme == 'tcp+ssl':
                ssl_context = ssl.create_default_context(ssl.Purpose.SERVER_AUTH)
                if endpoint.query and endpoint.query.getfirst('no_cert_validation') == '1':
                    ssl_context.check_hostname = False
                    ssl_context.verify_mode = ssl.CERT_NONE
            _, connection = await self._reactor.event_loop.create_connection(
                lambda: self._ClientConnection(self, endpoint), host, port, ssl=ssl_context
            )
            return connection

        try:
            return await do_connect()
        except OSError as e:
            raise exc.ConnectFailedError(
                f"Couldn't establish a TCP connection with {dump_to_url(endpoint)}", original_exc=e
            )

    class _ClientConnection(asyncio.Protocol, IStream):

        def __init__(self, creator: 'TCPClient', endpoint: Endpoint):
            self._id = _utils.next_unique_id(self.__class__)
            self._creator = creator
            self._endpoint = endpoint

        def connection_made(self, transport: asyncio.transports.BaseTransport):
            logger.info(
                'TCP client connected with %s using local address %r (id: %d)', dump_to_url(self._endpoint),
                transport.get_extra_info('sockname'), self._id
            )
            creator = self._creator
            self._target = _TCPStream(creator._reactor, transport)
            creator._active_connections[self._id] = self

        def connection_lost(self, exc: typing.Optional[Exception]):
            logger.info('TCP client connection lost (id: %d)', self._id)
            creator = self._creator
            del creator._active_connections[self._id]
            creator._reactor.run(self.close())

        def data_received(self, data: bytes) -> None:
            logger.debug('TCP client received %d bytes (id: %d)', len(data), self._id)
            self._target.data_received(data)

        def is_closed(self) -> bool:
            return self._target.is_closed()

        async def close(self):
            return await self._target.close()

        async def read(self, count: int) -> bytes:
            return await self._target.read(count)

        async def write(self, data: bytes) -> int:
            return await self._target.write(data)

        def get_write_buffer_size(self) -> int:
            return self._target.get_write_buffer_size()


class _TCPStream(IStream):

    def __init__(self, reactor: IReactor, transport: asyncio.transports.WriteTransport):
        self._transport = transport
        self._closed = False
        self._icoming_data_queue = asyncio.Queue()
        self._input_stream = QueueReadOnlyStream(self._icoming_data_queue)

    def data_received(self, data: bytes):
        self._icoming_data_queue.put_nowait(data)

    async def read(self, count: int) -> bytes:
        return await self._input_stream.read(count)

    async def write(self, data: bytes) -> int:
        if self._closed:
            raise exc.StreamClosedError()
        self._transport.write(data)
        return len(data)

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            await self._input_stream.close()
            self._transport.close()

    def get_write_buffer_size(self) -> int:
        return self._transport.get_write_buffer_size()
